<?php
declare(strict_types=1);
$app=is_file(__DIR__.'/../app/src/Database.php')?__DIR__.'/../app':'/var/www/html'; foreach(['Database','UserRepository','RepresentationOfferRepository','RepresentationRequestRepository'] as $class)require_once "$app/src/$class.php";
$check=static function(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);}; $pdo=(new Database(':memory:'))->connection();$now=gmdate('Y-m-d\TH:i:s\Z');
$pdo->exec("INSERT INTO organizations(org_id,org_type,chapter_name,meeting_day,timezone,created_at,updated_at)VALUES(101,'CHAPTER','Freitagschapter','Freitag','Europe/Berlin','$now','$now'),(202,'CHAPTER','Anbieterchapter','Montag','Europe/Berlin','$now','$now')");
