$requests=new RepresentationRequestRepository($pdo);$friday=(new DateTimeImmutable('next friday',new DateTimeZone('Europe/Berlin')))->format('Y-m-d');$friday2=(new DateTimeImmutable($friday))->modify('+7 days')->format('Y-m-d');$wednesday=(new DateTimeImmutable('next wednesday',new DateTimeZone('Europe/Berlin')))->format('Y-m-d');
