$afterRequests=['requests'=>(int)$pdo->query('SELECT COUNT(*) FROM representation_requests')->fetchColumn(),'offers'=>(int)$pdo->query('SELECT COUNT(*) FROM representation_offers')->fetchColumn(),'offer_dates'=>(int)$pdo->query('SELECT COUNT(*) FROM representation_offer_dates')->fetchColumn()];
