$loggedIn=$requests->activeForOrganizations([101],(int)$b['id'],date('Y-m-d'));$check($loggedIn[101][0]['displayName']==='Anna A.'&&$loggedIn[101][0]['canContact']&&isset($loggedIn[101][0]['requestId']),'Eingeloggte gebündelte Abfrage liefert Teilanonymisierung und sichere Referenz.');
$ownView=$requests->activeForOrganizations([101],(int)$a['id'],date('Y-m-d'));$check($ownView[101][0]['isOwn']&&!$ownView[101][0]['canContact']&&!isset($ownView[101][0]['requestId']),'Eigenes Gesuch ist nicht kontaktierbar.');
$duplicate=false;try{$requests->create((int)$a['id'],$friday);}catch(DomainException){$duplicate=true;}$check($duplicate,'Doppeltes Gesuch verhindert.');
$wrong=false;try{$requests->create((int)$a['id'],$wednesday);}catch(InvalidArgumentException){$wrong=true;}$check($wrong,'Falscher Meeting-Wochentag serverseitig abgewiesen.');
$past=false;try{$requests->create((int)$a['id'],'2020-01-01');}catch(InvalidArgumentException){$past=true;}$check($past,'Vergangenes Datum abgewiesen.');
$check(!$requests->deleteForUser($first['id'],(int)$b['id'])&&$requests->deleteForUser($first['id'],(int)$a['id']),'Ownership beim Löschen erzwungen.');
$offers=new RepresentationOfferRepository($pdo);$empty=$offers->findForHomeChapter(101,(int)$a['id'],date('Y-m-d'));
$check($empty['datedOffers']===[]&&$empty['allDatesOffers']===[],'Gesuch erzeugt keinen Eintrag in datedOffers.');
$always=$offers->createMany((int)$b['id'],[101],true,[])[0];$alwaysOnly=$offers->findForHomeChapter(101,(int)$a['id'],date('Y-m-d'));
$afterOffer=['requests'=>(int)$pdo->query('SELECT COUNT(*) FROM representation_requests')->fetchColumn(),'offers'=>(int)$pdo->query('SELECT COUNT(*) FROM representation_offers')->fetchColumn(),'offer_dates'=>(int)$pdo->query('SELECT COUNT(*) FROM representation_offer_dates')->fetchColumn()];
$check($afterOffer===['requests'=>$afterRequests['requests'],'offers'=>$afterRequests['offers']+1,'offer_dates'=>$afterRequests['offer_dates']],'Angebot schreibt ausschließlich representation_offers; die separate Gesuchsanlage und -löschung gleichen sich zuvor aus.');
$check($alwaysOnly['datedOffers']===[]&&count($alwaysOnly['allDatesOffers'])===1&&$alwaysOnly['allDatesOffers'][0]['offerId']===$always,'Immer-Angebot erzeugt ohne konkretes Angebot keinen künstlichen Termin.');
$datedOffer=$offers->createMany((int)$b['id'],[101],false,[$friday2])[0];$merged=$offers->findForHomeChapter(101,(int)$a['id'],date('Y-m-d'));$afterDatedOffer=['requests'=>(int)$pdo->query('SELECT COUNT(*) FROM representation_requests')->fetchColumn(),'offers'=>(int)$pdo->query('SELECT COUNT(*) FROM representation_offers')->fetchColumn(),'offer_dates'=>(int)$pdo->query('SELECT COUNT(*) FROM representation_offer_dates')->fetchColumn()];
$check($afterDatedOffer===['requests'=>$afterOffer['requests'],'offers'=>$afterOffer['offers']+1,'offer_dates'=>$afterOffer['offer_dates']+1],'Datumsangebot verändert keine Gesuche und schreibt Angebot plus Angebotstermin.');
$check(count($merged['datedOffers'])===1&&$merged['datedOffers'][0]['date']===$friday2&&$merged['datedOffers'][0]['providers'][0]['offerId']===$datedOffer,'Nur echtes datumsgebundenes Angebot erzeugt datedOffers; Anbieter wird angezeigt.');
$pdo->exec('DELETE FROM representation_offers');$emptyAgain=$offers->findForHomeChapter(101,(int)$a['id'],date('Y-m-d'));$check($emptyAgain['datedOffers']===[]&&$emptyAgain['allDatesOffers']===[],'Nach Entfernen der Angebote bleibt das Gesuch ausschließlich ein Gesuch.');
echo "PASS representation requests: Datum, Wochentag, Dublette, Ownership, Sortierung und Angebotszusammenführung\n";
